import sys
from functools import lru_cache

@lru_cache(maxsize=None)
def can_win(current, move_count):
    if move_count == 10:
        return False
    is_vanya_turn = (move_count % 2 == 0)
    if is_vanya_turn:
        for delta in (-1, 1):
            new_num = current + delta
            if new_num % 3 == 0:
                return True
            if not can_win(new_num, move_count + 1):
                return True
        return False
    else:
        for delta in (-1, 1):
            new_num = current + delta
            if not can_win(new_num, move_count + 1):
                return True
        return False

