from typing import List

class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        # Collect all indices where the element is x
        indices = []
        for i, num in enumerate(nums):
            if num == x:
                indices.append(i)

        # Process each query
        result = []
        for q in queries:
            if q > len(indices):
                result.append(-1)
            else:
                result.append(indices[q - 1])

        return result

import sys
from collections import defaultdict

MOD = 998244353

def is_palindrome(s):
    for i in range(len(s) // 2):
        if s[i] != s[-i - 1]:
            return False
    return True

def main():
    N, K = map(int, sys.stdin.readline().split())
    S = sys.stdin.readline().strip()

    prev_dp = defaultdict(int)
    first_char = S[0]
    if first_char == '?':
        prev_dp['A'] = 1
        prev_dp['B'] = 1
    else:
        prev_dp[first_char] = 1

    for i in range(1, N):
        curr_dp = defaultdict(int)
        current_char = S[i]
        possible_chars = ['A', 'B'] if current_char == '?' else [current_char]
        for state_prev, count in prev_dp.items():
            for c in possible_chars:
                if i >= K:
                    substring = state_prev + c
                    if is_palindrome(substring):
                        continue
                if len(state_prev) == K - 1:
                    new_state = state_prev[1:] + c
                else:
                    new_state = state_prev + c
                curr_dp[new_state] = (curr_dp[new_state] + count) % MOD
        prev_dp = curr_dp

    print(sum(prev_dp.values()) % MOD)

if __name__ == "__main__":
    main()

